(6484964, 963811, 70921, '<td valign="top">MOVE the subject off dead center (review rule of thirds) and flip the image so the subject faces left so when the eye enters the photo from left it doesn''t go into the back of subjects head.  NICE lighting, monotone color and effect.</td>', 'MOVE the subject off dead center (review rule of thirds) and flip the image so the subject faces left so when the eye enters the photo from left it doesn''t go into the back of subjects head.  NICE lighting, monotone color and effect.', '2011-07-30 13:14:08.000000', NULL, 1),
(6484965, 964111, 70921, '<td valign="top">Interesting texture and composition.</td>', 'Interesting texture and composition.', '2011-07-30 13:14:24.000000', NULL, 1),
(6484966, 963884, 70921, '<td valign="top">Mold on hand of statue just too distracting from what was a pretty good composition.  Lighting is too harsh.</td>', 'Mold on hand of statue just too distracting from what was a pretty good composition.  Lighting is too harsh.', '2011-07-30 13:15:11.000000', NULL, 1),
(6484967, 964086, 70921, '<td valign="top">Good "off centered subject" composition and pretty lighting.  I like the line and frame around the photo very much.</td>', 'Good "off centered subject" composition and pretty lighting.  I like the line and frame around the photo very much.', '2011-07-30 13:15:52.000000', NULL, 1),
(6484968, 963904, 70921, '<td valign="top">GREAT sky... good composition with just a hint of foreground and lots of the main subject (the sky).  I''d spot out that one bright tiny little street light at bottom right of the photo.</td>', 'GREAT sky... good composition with just a hint of foreground and lots of the main subject (the sky).  I''d spot out that one bright tiny little street light at bottom right of the photo.', '2011-07-30 13:16:43.000000', NULL, 1),
(6484969, 964087, 70921, '<td valign="top">GREAT composition, nice lighting and good focus</td>', 'GREAT composition, nice lighting and good focus', '2011-07-30 13:17:07.000000', NULL, 1),
