(6484971, 964081, 70921, '<td valign="top">Washed out and bland looking.  Good focus.  Subject too dead centered (review rule of thirds).</td>', 'Washed out and bland looking.  Good focus.  Subject too dead centered (review rule of thirds).', '2011-07-30 13:18:38.000000', NULL, 1),
(6484973, 964110, 70921, '<td valign="top">Nice composition with main subject NOT dead centered.  Good background, great depth of field and focus.  Nice lighting and movement in bird just entering the photo.</td>', 'Nice composition with main subject NOT dead centered.  Good background, great depth of field and focus.  Nice lighting and movement in bird just entering the photo.', '2011-07-30 13:19:37.000000', NULL, 1),
(6484974, 964035, 70921, '<td valign="top">I''d have cleaned off the spider webs on the compass... doesn''t add to rest of photo.  Good focus and composition. Glass object to left side is distracting from the rest of the background.</td>', 'I''d have cleaned off the spider webs on the compass... doesn''t add to rest of photo.  Good focus and composition. Glass object to left side is distracting from the rest of the background.', '2011-07-30 13:20:48.000000', NULL, 1),
(6484975, 964071, 70921, '<td valign="top">Simple and nice composition and lighting</td>', 'Simple and nice composition and lighting', '2011-07-30 13:21:11.000000', NULL, 1),
